import json

lines = open('ios_crash.ips').readlines()
crash = json.loads(''.join(lines[1:]))

# Get SampleMAUI images (there are 2)
for i, img in enumerate(crash['usedImages']):
    if 'SampleMAUI' in img.get('name', ''):
        print(f'Image [{i}]: name={img[\"name\"]} base=0x{img[\"base\"]:x} uuid={img[\"uuid\"]}')

# Show faulting thread SampleMAUI frames with their image index
ft = crash['threads'][crash['faultingThread']]
print('\nFaulting thread SampleMAUI frames:')
for i, f in enumerate(ft['frames']):
    img = crash['usedImages'][f['imageIndex']]
    if 'SampleMAUI' in img.get('name', ''):
        print(f'  #{i}: imageIndex={f[\"imageIndex\"]} base=0x{img[\"base\"]:x} offset=0x{f[\"imageOffset\"]:x}')

# Check lastExceptionBacktrace SampleMAUI frames
print('\nlastExceptionBacktrace SampleMAUI frames:')
for i, f in enumerate(crash.get('lastExceptionBacktrace', [])):
    img = crash['usedImages'][f['imageIndex']]
    if 'SampleMAUI' in img.get('name', ''):
        print(f'  #{i}: imageIndex={f[\"imageIndex\"]} base=0x{img[\"base\"]:x} offset=0x{f[\"imageOffset\"]:x}')
" 2>&1", "description": "Identify SampleMAUI image frames"}

