cd /tmp/sv-a7a10e248f9d49d6a57c8753210280ff && python3 -c "
import json

lines = open('ios_crash.ips').readlines()
crash = json.loads(''.join(lines[1:]))

# Check for termination info, vmRegionInfo, etc.
for key in ['termination', 'asi', 'vmRegionInfo', 'vmregioninfo', 'lastExceptionBacktrace', 'modelCode', 'coalitionName', 'procRole', 'pid']:
    if key in crash:
        val = crash[key]
        if key == 'lastExceptionBacktrace':
            print(f'{key}: [{len(val)} frames]')
        else:
            print(f'{key}: {json.dumps(val)}')

# Look for any text/reason fields
print()
for key in sorted(crash.keys()):
    if key not in ['usedImages', 'threads', 'lastExceptionBacktrace', 'binaryImages']:
        val = crash[key]
        if isinstance(val, (str, int, float, bool)):
            print(f'{key}: {val}')
        elif isinstance(val, dict) and len(str(val)) < 500:
            print(f'{key}: {json.dumps(val)}')
        elif isinstance(val, list) and len(str(val)) < 500:
            print(f'{key}: {json.dumps(val)}')
        else:
            print(f'{key}: [{type(val).__name__}]')
" 2>&1

